 function choose(event:React.FormEvent){event.preventDefault();const system=atlas.systems.find(row=>row.name.toLowerCase()===systemName.trim().toLowerCase());if(system)onSelectSystem(system.system_id);else setError('Choose a system from the atlas.');}
