 const bookmarkSettings=<details className="universe-disclosure universe-bookmark-format"><summary>Bookmark names</summary><div className="universe-operation-stack"><label className="field-label">Bookmark format<Input aria-label="Bookmark name format" value={bookmarkTemplate} onChange={event=>setBookmarkTemplate(event.target.value)} maxLength={240}/></label><p className="universe-operation-note">Tokens: {BOOKMARK_TOKENS.map(token=>'{'+token+'}').join(' · ')}</p>{bookmarkError?<p role="alert">{bookmarkError}</p>:<output aria-label="Bookmark name preview">{bookmarkPreview||'Choose a signature to preview this format.'}</output>}<p className="universe-operation-note">Copies a name for you to paste into EVE. A destination in this notebook is an observation; it does not create a live connection or a route.</p><details className="universe-bookmark-advanced"><summary>Labels and numbering</summary><div className="universe-operation-stack"><Toggle checked={bookmarkStartZero} onChange={setBookmarkStartZero}>Start new indices at zero</Toggle><p className="universe-operation-note">Existing signature indices stay unchanged. Chain labels are explicitly assigned in Signature naming; Kairo does not infer a branch tree from a changing wormhole graph.</p><label className="field-label">Return-hole symbol<Input aria-label="Bookmark return-hole symbol" maxLength={32} value={bookmarkReturnSymbol} onChange={event=>setBookmarkReturnSymbol(event.target.value)}/></label><label className="field-label">Label to customise<Choice label="Bookmark custom label" value={mappingKey} onChange={setMappingKey} options={BOOKMARK_MAPPINGS.map(row=>({value:row.key,label:row.label}))}/></label><label className="field-label">Replacement text<Input aria-label="Bookmark replacement text" value={bookmarkMapping[mappingKey]??BOOKMARK_MAPPINGS.find(row=>row.key===mappingKey)?.value??''} maxLength={32} onChange={event=>setBookmarkMapping(current=>({...current,[mappingKey]:event.target.value}))}/></label><button type="button" className="universe-record-action" onClick={()=>setBookmarkMapping(current=>{const next={...current};delete next[mappingKey];return next;})}>Reset this label</button></div></details><p className="universe-operation-note">{`{mass}`} is nominal total mass in billions of kg, never remaining mass. Life and mass-status tokens use an exact linked connection; unknown or ambiguous conditions stay blank. Time labels are bands from reported expiry.</p><Button variant="outline" disabled={busy||!!bookmarkError} onClick={saveBookmarkTemplate}>Save bookmark format</Button></div></details>;
 const scanReview=review&&preview&&<div className="universe-scan-review"><strong>Import into {selected?.name}</strong><p>{preview.added?.length||0} added · {preview.updated?.length||0} refreshed · {preview.missing?.length||0} marked missing · {preview.ignored||0} ignored</p><div className="universe-scan-diff">{[{key:'added',label:'New signatures'},{key:'updated',label:'Refreshed signatures'},{key:'missing',label:'Missing from complete scan'}].map(group=>!!preview[group.key]?.length&&<details key={group.key} open={group.key==='missing'}><summary>{group.label} ({preview[group.key].length})</summary><ul>{preview[group.key].map((row:any)=><li key={row.signature_id}>{row.signature_id} · {row.type||'Unknown'}{row.name?' · '+row.name:''}{row.changes?.length?' · changes: '+row.changes.join(', '):''}</li>)}</ul></details>)}{preview.diagnostics?.map((item:any,index:number)=><p key={index} role={item.severity==='error'?'alert':undefined}>{item.line?'Line '+item.line+': ':''}{item.reason}</p>)}</div><Button disabled={busy||previewBusy||preview.review_key!==scanKey||!preview.valid||!preview.signature_ids?.length} onClick={()=>void importScan()}><Check size={17}/>Import signatures</Button>{!preview.valid&&<p role="alert">Resolve the invalid rows before importing. Your notebook is unchanged.</p>}</div>;
